/* Producers call this method */
public synchronized void insert(E item) {
while (count == BUFFER SIZE) {
try {
wait();
}
catch (InterruptedException ie) {}
}
buffer[in] = item;
in = (in + 1) % BUFFER SIZE;
count++;
notify();
}
/* Consumers call this method */
public synchronized E remove() {
E item;
while (count == 0) {
try {
wait();
}
catch (InterruptedException ie) {}
}
item = buffer[out];
out = (out + 1) % BUFFER SIZE;
count--;
notify();
return item;
}
